import Component from 'flarum/common/Component';
import { t } from '../util';
const TOPICS = ['companions', 'dashboard', 'audit', 'score', 'links', 'indexnow', 'rules', 'diagnostics', 'settings', 'privacy'];

/** Plain-words help for each section. */
export default class Guide extends Component {
  view() {
    return m("div", {
      className: "SurveyorSection SurveyorGuide"
    }, TOPICS.map(topic => m("section", null, m("h3", null, t(`guide.${topic}_title`)), m("p", null, t(`guide.${topic}_body`)))));
  }
}
flarum.reg.add('ernestdefoe-surveyor', 'admin/workspace/Guide', Guide);